    Recipe(
      id: 'm53359',
      name: 'Beef Mandi',
      description: 'India Beef dish.',
      ingredientKeywords: ['basmati rice', 'beef stock', 'onion', 'garlic', 'green chilli', 'tomato', 'salt', 'oil', 'turmeric powder', 'cardamom', 'cloves', 'bay leaf'],
