    Recipe(
      id: 'm53021',
      name: 'Golabki (cabbage roll)',
      description: 'Polish Beef dish.',
      ingredientKeywords: ['cabbage', 'butter', 'onion', 'ground beef', 'ground pork', 'rice', 'garlic', 'salt', 'black pepper', 'tomato puree'],
      categories: ['Dairy', 'Meat'],
      ingredients: [
