      name: 'Turkish lahmacun',
      description: 'Vietnamese Beef dish.',
      ingredientKeywords: ['strong white bread flour', 'fast action yeast', 'corn flour', 'tomato', 'green chilli', 'spring onions', 'parsley', 'ground beef', 'chilli flakes', 'ground cumin', 'allspice', 'olive oil', 'lemon', 'red onions'],
      categories: ['Bakery', 'Meat'],
      ingredients: [
