    Recipe(
      id: 'm52918',
      name: 'Fish Stew with Rouille',
      description: 'France Seafood dish.',
      ingredientKeywords: ['prawns', 'olive oil', 'dry white wine', 'fish stock', 'fennel', 'onion', 'garlic', 'potatoes', 'orange', 'star anise', 'bay leaf', 'harissa spice', 'tomato puree', 'chopped tomatoes', 'mussels', 'white fish', 'thyme', 'bread'],
      categories: ['Bakery', 'Beverages', 'Seafood'],
      ingredients: [
